create type public.alert_type as enum (
  'new_listing', 'price_reduction', 'excellent_opportunity', 'listing_removed'
);

-- Notifications generated by the backend for a user.
create table public.alerts (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  saved_search_id uuid references public.saved_searches (id) on delete set null,
  listing_id      uuid not null references public.listings (id) on delete cascade,
  type            public.alert_type not null,

  -- context for the message, e.g. "reduced from 9700 to 9300"
  old_price       numeric(10, 2),
  new_price       numeric(10, 2),

  read_at         timestamptz,
  created_at      timestamptz not null default now()
);

-- "My alerts, newest first" is the main query.
create index alerts_user_created_idx on public.alerts (user_id, created_at desc);
create index alerts_listing_idx on public.alerts (listing_id);

alter table public.alerts enable row level security;

-- Users read and delete their own alerts. Inserts come from the backend
-- (service role), which bypasses RLS.
create policy "Users read their own alerts"
  on public.alerts for select to authenticated
  using (user_id = (select auth.uid()));

create policy "Users delete their own alerts"
  on public.alerts for delete to authenticated
  using (user_id = (select auth.uid()));

-- Users may only mark alerts as read, not edit anything else.
create policy "Users mark their own alerts as read"
  on public.alerts for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

revoke update on public.alerts from authenticated;
grant update (read_at) on public.alerts to authenticated;